from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    fill = Counter(v for row in grid for v in row).most_common(1)[0][0]

    def mode(values):
        return Counter(values).most_common(1)[0][0]

    row_modes = [mode(row) for row in grid]
    col_modes = [mode(grid[r][c] for r in range(h)) for c in range(w)]

    rows = [r for r, v in enumerate(row_modes) if v != fill]
    cols = [c for c, v in enumerate(col_modes) if v != fill]
    if len(rows) < 2 or len(cols) < 2:
        return [[fill]]

    border = mode([row_modes[r] for r in rows] +
                  [col_modes[c] for c in cols])

    def active(r, c):
        return any(grid[r][c] != border
                   for r in rows) if False else False

    # Discard unmarked outer grid lines, as they are margins rather than
    # boundaries of the encoded output.
    def line_has_marker(is_row, idx):
        if is_row:
            return any(grid[idx][c] != border for c in cols)
        return any(grid[r][idx] != border for r in rows)

    while len(rows) > 2 and not line_has_marker(True, rows[0]):
        rows.pop(0)
    while len(rows) > 2 and not line_has_marker(True, rows[-1]):
        rows.pop()
    while len(cols) > 2 and not line_has_marker(False, cols[0]):
        cols.pop(0)
    while len(cols) > 2 and not line_has_marker(False, cols[-1]):
        cols.pop()

    out = []
    for i in range(len(rows) - 1):
        row = []
        for j in range(len(cols) - 1):
            corners = [
                grid[rows[i]][cols[j]],
                grid[rows[i]][cols[j + 1]],
                grid[rows[i + 1]][cols[j]],
                grid[rows[i + 1]][cols[j + 1]],
            ]
            if corners[0] != border and all(v == corners[0] for v in corners):
                row.append(corners[0])
            else:
                row.append(fill)
        out.append(row)
    return out
